-- CREATE TRIGGER AFTER INSERT
CREATE TRIGGER trg_audit
AFTER INSERT ON users
FOR EACH ROW
EXECUTE FUNCTION audit_func();

-- CREATE TRIGGER BEFORE UPDATE OR DELETE
CREATE TRIGGER trg_protect
BEFORE DELETE OR UPDATE ON orders
FOR EACH ROW
EXECUTE FUNCTION protect_func();

-- CREATE TRIGGER FOR EACH STATEMENT
CREATE TRIGGER trg_log
AFTER INSERT ON logs
FOR EACH STATEMENT
EXECUTE FUNCTION log_func();

-- CREATE CONSTRAINT TRIGGER
CREATE CONSTRAINT TRIGGER trg_fk_check
AFTER INSERT ON order_items
FOR EACH ROW
EXECUTE FUNCTION check_fk();

-- CREATE DOMAIN with CHECK
CREATE DOMAIN email_address AS text CHECK (value ~ '^.+@.+$');

-- CREATE DOMAIN with NOT NULL
CREATE DOMAIN positive_int AS int NOT NULL CHECK (value > 0);

-- ALTER SEQUENCE
ALTER SEQUENCE order_id_seq RESTART WITH 100;

-- REINDEX TABLE
REINDEX TABLE users;

-- REINDEX INDEX
REINDEX INDEX idx_users_email;

-- CLUSTER
CLUSTER users USING users_pkey;

